import fs from "node:fs/promises";
import path from "node:path";
import {
  removeOwnedOutputFile,
  writeOwnedOutputFile,
} from "../output/owned-file-output.js";

export const PLUGIN_TYPES_FILE = "plugin-types.d.ts";
export const PLUGIN_TYPES_MARKER =
  "// @generated by evjs/plugin-types. Do not edit this file.";
export const PLUGIN_TYPES_USAGE_HINT =
  "// Do not import this file from application code; include its directory in tsconfig instead.";
export const PLUGIN_TYPES_REGISTER_MODULE = "@evjs/ev/config";

const CONFIG_FILES = ["ev.config.ts", "ev.config.js", "ev.config.mjs"] as const;

export interface GeneratePluginTypesOptions {
  /** Set false when a JavaScript config cannot provide safe static types. */
  configModule?: string | false;
  registerModule?: string;
}

export interface PluginTypesPath {
  dir: string;
  file: string;
  configModule: string;
}

export interface SyncPluginTypesOptions {
  cwd: string;
  configSource?: string;
}

/** Generate project-local registry augmentation from the static `ev.config.*` type. */
export function generatePluginTypes({
  configModule = "../ev.config",
  registerModule = PLUGIN_TYPES_REGISTER_MODULE,
}: GeneratePluginTypesOptions): string {
  const registryBody =
    configModule === false
      ? [
          "    // Exact Page plugin types require ev.config.ts; JavaScript config imports become any when allowJs is disabled.",
        ]
      : [
          "    // @ts-ignore -- ev.config.ts intentionally lives outside src/rootDir.",
          `    readonly config: typeof import(${JSON.stringify(configModule)}).default;`,
        ];
  return [
    "/* eslint-disable */",
    PLUGIN_TYPES_MARKER,
    PLUGIN_TYPES_USAGE_HINT,
    `declare module ${JSON.stringify(registerModule)} {`,
    "  interface InstalledPluginRegistry {",
    ...registryBody,
    "  }",
    "}",
    "",
    "export {};",
    "",
  ].join("\n");
}

/** Resolve the declaration path and config type import for one project. */
export function getPluginTypesPath(
  cwd: string,
  configSource = "ev.config.ts",
): PluginTypesPath {
  const projectRoot = path.resolve(cwd);
  // Keep ambient declarations in src: generated IR under .ev is intentionally
  // outside the application tsconfig in standard projects.
  const dir = path.join(projectRoot, "src");
  const absoluteConfigSource = path.resolve(projectRoot, configSource);

  return {
    dir,
    file: path.join(dir, PLUGIN_TYPES_FILE),
    configModule: toTypeImportSpecifier(dir, absoluteConfigSource),
  };
}

export async function collectGeneratedPluginTypeFiles(
  cwd: string,
): Promise<string[]> {
  const file = getPluginTypesPath(cwd).file;
  return (await isGeneratedPluginTypesFile(file)) ? [file] : [];
}

export async function isGeneratedPluginTypesFile(
  file: string,
): Promise<boolean> {
  try {
    const stats = await fs.lstat(file);
    if (stats.isSymbolicLink() || !stats.isFile()) return false;
    const source = await fs.readFile(file, "utf-8");
    return isOwnedPluginTypesSource(source);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

export async function writePluginTypesIfChanged(
  file: string,
  source: string,
  rootDir = path.dirname(path.dirname(file)),
): Promise<void> {
  try {
    const stats = await fs.lstat(file);
    if (stats.isSymbolicLink()) {
      throw new Error(
        "[evjs] Plugin types output must not overwrite a symbolic-link output file.",
      );
    }
    const current = await fs.readFile(file, "utf-8");
    if (current === source) return;
    if (!isOwnedPluginTypesSource(current)) {
      throw new Error(
        "[evjs] Plugin types output must not overwrite a user-owned output file.",
      );
    }
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
  }

  await writeOwnedOutputFile(rootDir, file, source, "Plugin types output");
}

/** Remove the canonical declaration only when evjs owns its contents. */
export async function removeGeneratedPluginTypes(
  cwd: string,
): Promise<boolean> {
  const file = getPluginTypesPath(cwd).file;
  if (!(await isGeneratedPluginTypesFile(file))) return false;

  await removeOwnedOutputFile(cwd, file, "Plugin types output");
  return true;
}

/** Write the static project-config registry used by Page plugin type inference. */
export async function syncPluginTypes({
  cwd,
  configSource,
}: SyncPluginTypesOptions): Promise<void> {
  const resolvedConfigSource =
    configSource ?? (await discoverPluginConfigSource(cwd));
  if (!resolvedConfigSource) {
    await removeGeneratedPluginTypes(cwd);
    return;
  }
  const { file, configModule } = getPluginTypesPath(cwd, resolvedConfigSource);
  const source = generatePluginTypes({
    configModule: resolvedConfigSource.endsWith(".ts") ? configModule : false,
  });
  await writePluginTypesIfChanged(file, source, cwd);
}

async function discoverPluginConfigSource(
  cwd: string,
): Promise<string | undefined> {
  for (const fileName of CONFIG_FILES) {
    const file = path.resolve(cwd, fileName);
    try {
      const stats = await fs.lstat(file);
      if (stats.isFile()) return file;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    }
  }
  return undefined;
}

function isOwnedPluginTypesSource(source: string): boolean {
  return source.startsWith(createOwnedTypesHeader(PLUGIN_TYPES_MARKER));
}

function createOwnedTypesHeader(marker: string): string {
  return `/* eslint-disable */\n${marker}\n${PLUGIN_TYPES_USAGE_HINT}\n`;
}

function toTypeImportSpecifier(fromDir: string, source: string): string {
  const extensionless = source.replace(/\.[jt]sx?$/, "");
  const relative = path
    .relative(fromDir, extensionless)
    .split(path.sep)
    .join("/");
  return relative.startsWith(".") ? relative : `./${relative}`;
}
